import{_ as a,o as s,c as t,a2 as o}from"./chunks/framework.LX5S0jbT.js";const m=JSON.parse('{"title":"Local Models with llama.cpp","description":"","frontmatter":{},"headers":[],"relativePath":"llama-cpp.md","filePath":"llama-cpp.md"}'),i={name:"llama-cpp.md"};function l(n,e,d,r,c,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="local-models-with-llama-cpp" tabindex="-1">Local Models with llama.cpp <a class="header-anchor" href="#local-models-with-llama-cpp" aria-label="Permalink to &quot;Local Models with llama.cpp&quot;">​</a></h1><p>Pi supports the <a href="https://github.com/ggml-org/llama.cpp" target="_blank" rel="noreferrer">llama.cpp</a> router server. The router discovers multiple GGUF models and loads or unloads them on demand.</p><p>Use a current llama.cpp build with router support. Follow the <a href="https://github.com/ggml-org/llama.cpp/blob/master/docs/build.md" target="_blank" rel="noreferrer">build instructions</a> or install a <a href="https://github.com/ggml-org/llama.cpp/releases" target="_blank" rel="noreferrer">prebuilt release</a> for your platform.</p><h2 id="start-the-router" tabindex="-1">Start the router <a class="header-anchor" href="#start-the-router" aria-label="Permalink to &quot;Start the router&quot;">​</a></h2><p>Start <code>llama-server</code> without <code>--model</code> or <code>-m</code>. Passing a model starts single-model mode instead of router mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">llama-server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --models-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/models</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --no-models-autoload</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --jinja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -ngl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 999</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32768</span></span></code></pre></div><p>Important options:</p><ul><li><code>--models-dir ~/models</code> discovers local GGUF files.</li><li><code>--no-models-autoload</code> keeps loading explicit through <code>/llama</code>.</li><li><code>--jinja</code> enables compatible chat templates and tool calling.</li><li><code>-ngl 999</code> offloads as many layers as possible to the GPU.</li><li><code>-c 32768</code> sets the context window for each loaded model. Omit it to use the model&#39;s native context, which may require substantially more memory.</li></ul><p>A single-file model can sit directly in the model directory. Put multimodal and multi-shard models in separate subdirectories:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/models/</span></span>
<span class="line"><span>├── llama-3.2-1b-Q4_K_M.gguf</span></span>
<span class="line"><span>├── gemma-3-4b-it-Q4_K_M/</span></span>
<span class="line"><span>│   ├── gemma-3-4b-it-Q4_K_M.gguf</span></span>
<span class="line"><span>│   └── mmproj-F16.gguf</span></span>
<span class="line"><span>└── large-model-Q4_K_M/</span></span>
<span class="line"><span>    ├── large-model-Q4_K_M-00001-of-00003.gguf</span></span>
<span class="line"><span>    ├── large-model-Q4_K_M-00002-of-00003.gguf</span></span>
<span class="line"><span>    └── large-model-Q4_K_M-00003-of-00003.gguf</span></span></code></pre></div><p>Restart the router after manually adding files. For per-model context sizes and other options, use <a href="https://github.com/ggml-org/llama.cpp/blob/master/tools/server/README.md#model-presets" target="_blank" rel="noreferrer">llama.cpp model presets</a>. For settings tuned to a specific NVIDIA GPU and model, see <a href="./nvidia-rtx-llama-cpp.html">Run Pi with NVIDIA RTX and llama.cpp</a>.</p><h2 id="configure-pi" tabindex="-1">Configure Pi <a class="header-anchor" href="#configure-pi" aria-label="Permalink to &quot;Configure Pi&quot;">​</a></h2><p>Start Pi and configure the provider:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/login llama.cpp</span></span></code></pre></div><p>Enter the router URL and optional API key. The default URL is <code>http://127.0.0.1:8080</code>.</p><p>If you start the router with <code>--no-models-autoload</code>, <code>/login llama.cpp</code> only stores the connection. Run <code>/llama</code> to load a model, then <code>/model</code> to select the loaded model for the current session.</p><p>Environment variables can configure the same values without <code>/login</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLAMA_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:8080</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LLAMA_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">optional-secret</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span></span></code></pre></div><p>If the server uses an API key, start <code>llama-server</code> with the matching <code>--api-key</code> value. Keep <code>--host 127.0.0.1</code> for local-only access.</p><h2 id="manage-models" tabindex="-1">Manage models <a class="header-anchor" href="#manage-models" aria-label="Permalink to &quot;Manage models&quot;">​</a></h2><p>Run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/llama</span></span></code></pre></div><ul><li>Select an unloaded model to load it.</li><li>Select a loaded model to unload it.</li><li>Select <strong>Download model…</strong>, search Hugging Face, then choose a repository and quantization. Exact <code>owner/repository[:quant]</code> values also work.</li><li>Press Escape during a load or download to confirm cancellation.</li></ul><p>Hugging Face search uses <code>HF_TOKEN</code> when set, then checks <code>$HF_TOKEN_PATH</code>, <code>$HF_HOME/token</code>, <code>$XDG_CACHE_HOME/huggingface/token</code>, and <code>~/.cache/huggingface/token</code>. Search also works without authentication, subject to lower rate limits. Pi warns before downloading gated repositories and links to their access page. The llama.cpp server performs the download, so its process must also have <code>HF_TOKEN</code> when the selected repository requires access.</p><p>If other models are loaded, Pi asks whether to unload them first or keep them loaded. Pi does not silently unload models and never deletes model files. The router may be shared with other clients, so <code>/llama</code> always displays the router&#39;s current state.</p><p>Loaded and sleeping models appear in <code>/model</code>. Sleeping models wake automatically when selected. With router autoload enabled, unloaded preset models also appear and load when selected. With <code>--no-models-autoload</code>, load a model through <code>/llama</code> before selecting it.</p><p>If the router disconnects, <code>/llama</code> shows <strong>Retry</strong> and <strong>Close</strong>. Retry reconnects and refreshes model state without replaying the interrupted operation.</p><h2 id="classification" tabindex="-1">Classification <a class="header-anchor" href="#classification" aria-label="Permalink to &quot;Classification&quot;">​</a></h2><p>Classifier models answer typed <code>choice</code>, <code>bool</code>, and <code>score</code> questions about JSON state, like TypeSafe&#39;s Jev models. The model reaches them from <a href="./cli.html#enable-codemode"><code>codemode</code></a> scripts, and extensions through <code>ctx.modelRegistry.classify()</code>; see <a href="./models.html#use-classifier-models">Classifier models</a>. Pi lists llama.cpp models as classifiers in two ways:</p><ul><li><strong>Decision models</strong> such as <a href="https://huggingface.co/collections/ggml-org/decision-models-6abf80cca3c83f127060a769" target="_blank" rel="noreferrer">Julia-1, Laya, Kev, lev, and OpenJev</a> answer natively through llama.cpp&#39;s <code>/v1/systemone</code> endpoint. They appear only as classifiers, with the <code>typesafe-system-one</code> API, and not in <code>/model</code>.</li><li><strong>Chat models</strong> are also listed as classifiers with the same ID and the <code>llama-cpp-classify</code> API, which reads answers from next-token probabilities as described below.</li></ul><p>llama.cpp 0.6.0 and later report decision models in the router&#39;s model list: their <code>architecture.output_modalities</code> contains <code>decisions</code>. The router reads this from the GGUF metadata without loading the model, so Pi recognizes unloaded and sleeping decision models too. Older llama.cpp builds do not report it, and Pi lists their decision models as chat models.</p><h3 id="chat-models-as-classifiers" tabindex="-1">Chat models as classifiers <a class="header-anchor" href="#chat-models-as-classifiers" aria-label="Permalink to &quot;Chat models as classifiers&quot;">​</a></h3><p>The model does not generate an answer. Each question becomes one chat prompt: the state, every question of the request, the state again, and then the question with its answers under single-token labels. Labels are letters for a choice (up to 62 options), <code>Yes</code>/<code>No</code> for a bool, and digits for a score (up to 10 levels). The second copy of the state is read with the questions in view, which improved accuracy on JevBench with small models. Pi reads the probabilities of the labels as the next token and normalizes them. A choice returns every option&#39;s probability and a confidence of <code>(n * peak - 1) / (n - 1)</code>; a score returns the expected level.</p><ul><li>Raw label probabilities are usually overconfident. The per-request <code>temperature</code> option divides the label logits before normalizing; values above 1 soften the distribution. It changes no answer.</li><li>Questions run one after another. Everything before the final question is the same for all questions of a request, so the server&#39;s prompt cache evaluates it once. The state appears twice, so it needs twice its size in context.</li><li>Small models may follow instructions written inside the state. The prompt tells the model to judge the state as data, but that is not a guarantee.</li><li>Hybrid models such as Qwen3.5 cannot rewind a partially cached prompt without context checkpoints. If each question reprocesses the whole state, start the router with <code>--ctx-checkpoints 32 --checkpoint-min-step 0</code>.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>Check that the router is reachable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8080/models</span></span></code></pre></div><ul><li><strong>No models in <code>/llama</code>:</strong> Check <code>--models-dir</code>, the directory layout, and restart the router.</li><li><strong>Model missing from <code>/model</code> with <code>--no-models-autoload</code>:</strong> Load it with <code>/llama</code> first.</li><li><strong>Load fails or uses too much memory:</strong> Lower <code>-c</code> or unload another model.</li><li><strong>Server is not in router mode:</strong> Start it without <code>--model</code>, <code>-m</code>, or <code>-hf</code>.</li></ul><p>To remove the <code>llama.cpp</code> provider and <code>/llama</code>, disable <code>llama.cpp</code> under Built-in in <code>pi config</code>, or set <code>&quot;extensions&quot;: [&quot;-builtin:llama.cpp&quot;]</code> in <a href="./settings.html#resources">settings</a>.</p>`,39)])])}const u=a(i,[["render",l]]);export{m as __pageData,u as default};
